//! Native-only vault service. Secret commands require the dedicated vault webview.
use crate::vault_core::{self as core, Entry, Vault, Key};
use serde::{Deserialize,Serialize};
use std::{path::PathBuf,sync::{Mutex,MutexGuard,atomic::{AtomicU64,Ordering}},time::{Duration,Instant,SystemTime}};
use tauri::{AppHandle,Emitter,Manager,State,WebviewWindow,WebviewWindowBuilder,WebviewUrl};
use tauri_plugin_dialog::DialogExt;
use tauri_plugin_clipboard_manager::ClipboardExt;
use zeroize::{Zeroize,ZeroizeOnDrop,Zeroizing};
const IDLE:Duration=Duration::from_secs(300);
pub struct Session{data:Vault,key:Key,salt:[u8;16],fingerprint:[u8;32],touched:Instant,wall:SystemTime}
impl Session{fn expired(&self)->bool{self.touched.elapsed()>=IDLE||self.wall.elapsed().unwrap_or(IDLE)>=IDLE}fn touch(&mut self){self.touched=Instant::now();self.wall=SystemTime::now();}}
pub struct VaultState{session:Mutex<Option<Session>>,epoch:AtomicU64,clipboard:Mutex<Option<Zeroizing<String>>>,clipboard_epoch:AtomicU64,next_try:Mutex<Option<Instant>>}
impl Default for VaultState{fn default()->Self{Self{session:Mutex::new(None),epoch:AtomicU64::new(0),clipboard:Mutex::new(None),clipboard_epoch:AtomicU64::new(0),next_try:Mutex::new(None)}}}
fn location(app:&AppHandle)->Result<PathBuf,String>{app.path().app_config_dir().map(|p|p.join("password-vault.mtvault")).map_err(|_|"Vault storage is unavailable".into())}
fn authorised(window:&WebviewWindow)->Result<(),String>{if window.label()!="vault"{Err("Vault commands are restricted to the vault window".into())}else{Ok(())}}
fn active(state:&VaultState)->Result<MutexGuard<'_,Option<Session>>,String>{let mut g=state.session.lock().map_err(|_|"Vault is unavailable")?;if g.as_ref().is_some_and(Session::expired){g.take();state.epoch.fetch_add(1,Ordering::SeqCst);}if g.is_none(){return Err("Vault is locked".into());}g.as_mut().unwrap().touch();Ok(g)}
fn clear_clipboard(app:&AppHandle,state:&VaultState){state.clipboard_epoch.fetch_add(1,Ordering::SeqCst);if let Ok(mut owned)=state.clipboard.lock(){if let Some(secret)=owned.take(){if let Ok(text)=app.clipboard().read_text(){let current=Zeroizing::new(text);if current.as_str()==secret.as_str(){let _=app.clipboard().clear();}}}}}
fn lock_inner(app:&AppHandle,clear:bool){let state=app.state::<VaultState>();state.epoch.fetch_add(1,Ordering::SeqCst);if let Ok(mut session)=state.session.lock(){session.take();}if clear{clear_clipboard(app,&state);}let _=app.emit_to("vault","vault-locked",());}
pub fn lock(app:&AppHandle){lock_inner(app,true)}
pub fn blur_lock(app:&AppHandle){lock_inner(app,false)}
pub fn start_timer(app:AppHandle){tauri::async_runtime::spawn(async move{loop{tokio::time::sleep(Duration::from_secs(5)).await;let state=app.state::<VaultState>();let expired=state.session.lock().map(|s|s.as_ref().is_some_and(Session::expired)).unwrap_or(true);if expired{lock(&app);}}});}
#[tauri::command]pub async fn open_vault(app:AppHandle,window:WebviewWindow)->Result<(),String>{if window.label()!="main"{return Err("Open the vault from MyTools".into());}if let Some(w)=app.get_webview_window("vault"){let _=w.show();let _=w.set_focus();return Ok(());}WebviewWindowBuilder::new(&app,"vault",WebviewUrl::App("vault.html".into())).title("MyTools — Password Vault").inner_size(1120.0,780.0).min_inner_size(850.0,600.0).center().on_navigation(|u|{u.path()=="/vault.html"&&((u.scheme()=="tauri"&&u.host_str()==Some("localhost"))||(["http","https"].contains(&u.scheme())&&u.host_str()==Some("tauri.localhost")))}).build().map_err(|_|"Could not open the vault window")?;Ok(())}
#[derive(Serialize)]pub struct Status{exists:bool,unlocked:bool,entries:usize,auto_lock_seconds:u32}
#[tauri::command]pub fn vault_status(app:AppHandle,window:WebviewWindow,state:State<VaultState>)->Result<Status,String>{authorised(&window)?;let mut g=state.session.lock().map_err(|_|"Vault unavailable")?;if g.as_ref().is_some_and(Session::expired){g.take();state.epoch.fetch_add(1,Ordering::SeqCst);}Ok(Status{exists:location(&app)?.exists(),unlocked:g.is_some(),entries:g.as_ref().map(|s|s.data.entries.iter().filter(|e|!e.deleted).count()).unwrap_or(0),auto_lock_seconds:300})}
#[tauri::command]pub fn vault_lock(app:AppHandle,window:WebviewWindow)->Result<(),String>{authorised(&window)?;lock(&app);Ok(())}
#[tauri::command]pub fn vault_touch(window:WebviewWindow,state:State<VaultState>)->Result<(),String>{authorised(&window)?;drop(active(&state)?);Ok(())}
fn set_session(app:&AppHandle,data:Vault,key:Key,salt:[u8;16],fingerprint:[u8;32],epoch:u64)->Result<(),String>{let state=app.state::<VaultState>();let mut g=state.session.lock().map_err(|_|"Vault unavailable")?;if state.epoch.load(Ordering::SeqCst)!=epoch{return Err("Vault remained locked because focus changed. Try again.".into());}*g=Some(Session{data,key,salt,fingerprint,touched:Instant::now(),wall:SystemTime::now()});Ok(())}
#[tauri::command]pub async fn vault_create(app:AppHandle,window:WebviewWindow,password:String)->Result<(),String>{authorised(&window)?;let password=Zeroizing::new(password);if password.chars().count()<12||password.len()>4096{return Err("Use at least 12 characters for the master password".into());}let epoch=app.state::<VaultState>().epoch.load(Ordering::SeqCst);tauri::async_runtime::spawn_blocking(move||{let path=location(&app)?;let salt=core::new_salt()?;let key=core::derive(&password,&salt)?;let data=Vault::default();let bytes=core::seal(&data,&key,&salt)?;core::create(&path,&bytes)?;set_session(&app,data,key,salt,core::fingerprint(&bytes),epoch)}).await.map_err(|_|"Vault creation failed")?}
#[tauri::command]pub async fn vault_unlock(app:AppHandle,window:WebviewWindow,password:String)->Result<(),String>{authorised(&window)?;let password=Zeroizing::new(password);let state=app.state::<VaultState>();if state.next_try.lock().map_err(|_|"Vault unavailable")?.is_some_and(|t|Instant::now()<t){return Err("Wait a moment before trying again".into());}let epoch=state.epoch.load(Ordering::SeqCst);drop(state);tauri::async_runtime::spawn_blocking(move||{let bytes=core::read(&location(&app)?)?;let salt=core::header_salt(&bytes)?;let key=core::derive(&password,&salt)?;let data=match core::open(&bytes,&key){Ok(v)=>v,Err(_)=>{*app.state::<VaultState>().next_try.lock().map_err(|_|"Vault unavailable")?=Some(Instant::now()+Duration::from_secs(2));return Err("Unable to unlock. Check your master password or restore an encrypted backup.".into());}};set_session(&app,data,key,salt,core::fingerprint(&bytes),epoch)}).await.map_err(|_|"Vault unlock failed")?}
#[derive(Serialize)]pub struct Summary{id:String,title:String,username:String,url:String,folder:String,favourite:bool,deleted:bool,modified:u64}
#[tauri::command]pub fn vault_list(window:WebviewWindow,state:State<VaultState>)->Result<Vec<Summary>,String>{authorised(&window)?;let g=active(&state)?;Ok(g.as_ref().unwrap().data.entries.iter().map(|e|Summary{id:e.id.clone(),title:e.title.clone(),username:e.username.clone(),url:e.url.clone(),folder:e.folder.clone(),favourite:e.favourite,deleted:e.deleted,modified:e.modified}).collect())}
#[derive(Serialize)]pub struct Details{id:String,title:String,username:String,url:String,notes:String,folder:String,favourite:bool,created:u64,modified:u64}
#[tauri::command]pub fn vault_get(window:WebviewWindow,state:State<VaultState>,id:String)->Result<Details,String>{authorised(&window)?;let g=active(&state)?;let e=g.as_ref().unwrap().data.entries.iter().find(|e|e.id==id).ok_or("Entry not found")?;Ok(Details{id:e.id.clone(),title:e.title.clone(),username:e.username.clone(),url:e.url.clone(),notes:e.notes.clone(),folder:e.folder.clone(),favourite:e.favourite,created:e.created,modified:e.modified})}
#[derive(Deserialize,Zeroize,ZeroizeOnDrop)]pub struct Input{pub id:Option<String>,pub title:String,pub username:String,pub url:String,pub notes:String,pub folder:String,pub password:Option<String>,pub favourite:bool}
fn persist_session(app:&AppHandle,s:&mut Session,candidate:Vault)->Result<(),String>{let bytes=core::seal(&candidate,&s.key,&s.salt)?;core::commit(&location(app)?,&bytes,&s.fingerprint)?;s.data=candidate;s.fingerprint=core::fingerprint(&bytes);s.touch();Ok(())}
#[tauri::command]pub async fn vault_save(app:AppHandle,window:WebviewWindow,input:Input)->Result<String,String>{authorised(&window)?;tauri::async_runtime::spawn_blocking(move||{let state=app.state::<VaultState>();let mut g=active(&state)?;let s=g.as_mut().unwrap();let mut candidate=s.data.clone();let now=core::now();let id=if let Some(id)=&input.id{let e=candidate.entries.iter_mut().find(|e|e.id==*id&&!e.deleted).ok_or("Entry not found")?;e.title=input.title.trim().into();e.username=input.username.clone();e.url=input.url.clone();e.notes=input.notes.clone();e.folder=input.folder.clone();e.favourite=input.favourite;if let Some(p)=&input.password{e.password=p.clone();}e.modified=now;id.clone()}else{let id=core::new_id()?;candidate.entries.push(Entry{id:id.clone(),title:input.title.trim().into(),username:input.username.clone(),password:input.password.clone().unwrap_or_default(),url:input.url.clone(),notes:input.notes.clone(),folder:input.folder.clone(),favourite:input.favourite,deleted:false,created:now,modified:now});id};persist_session(&app,s,candidate)?;Ok(id)}).await.map_err(|_|"Entry save failed")?}
#[tauri::command]pub async fn vault_archive(app:AppHandle,window:WebviewWindow,id:String,deleted:bool)->Result<(),String>{authorised(&window)?;tauri::async_runtime::spawn_blocking(move||{let state=app.state::<VaultState>();let mut g=active(&state)?;let s=g.as_mut().unwrap();let mut candidate=s.data.clone();let e=candidate.entries.iter_mut().find(|e|e.id==id).ok_or("Entry not found")?;e.deleted=deleted;e.modified=core::now();persist_session(&app,s,candidate)}).await.map_err(|_|"Entry update failed")?}
#[tauri::command]pub fn vault_reveal(window:WebviewWindow,state:State<VaultState>,id:String)->Result<String,String>{authorised(&window)?;let g=active(&state)?;Ok(g.as_ref().unwrap().data.entries.iter().find(|e|e.id==id&&!e.deleted).ok_or("Entry not found")?.password.clone())}
#[tauri::command]pub fn vault_copy(app:AppHandle,window:WebviewWindow,state:State<VaultState>,id:String)->Result<(),String>{authorised(&window)?;let secret={let g=active(&state)?;Zeroizing::new(g.as_ref().unwrap().data.entries.iter().find(|e|e.id==id&&!e.deleted).ok_or("Entry not found")?.password.clone())};app.clipboard().write_text(secret.as_str()).map_err(|_|"Could not copy password")?;let token=state.clipboard_epoch.fetch_add(1,Ordering::SeqCst)+1;*state.clipboard.lock().map_err(|_|"Clipboard unavailable")?=Some(secret);tauri::async_runtime::spawn(async move{tokio::time::sleep(Duration::from_secs(30)).await;let state=app.state::<VaultState>();if state.clipboard_epoch.load(Ordering::SeqCst)==token{clear_clipboard(&app,&state);}});Ok(())}
#[tauri::command]pub async fn vault_backup(app:AppHandle,window:WebviewWindow,state:State<'_,VaultState>)->Result<bool,String>{authorised(&window)?;{let _guard=active(&state)?;}let bytes=core::read(&location(&app)?)?;tauri::async_runtime::spawn_blocking(move||{let Some(file)=app.dialog().file().set_title("Save encrypted vault backup").set_file_name("MyTools-backup.mtvault").add_filter("Encrypted MyTools vault",&["mtvault"]).blocking_save_file()else{return Ok(false)};let path=file.into_path().map_err(|_|"Invalid backup location")?;if path==location(&app)?{return Err("Choose a backup location outside the active vault".into());}core::export_encrypted(&path,&bytes)?;Ok(true)}).await.map_err(|_|"Backup export failed")?}
#[tauri::command]pub async fn vault_restore(app:AppHandle,window:WebviewWindow,password:String)->Result<bool,String>{authorised(&window)?;let password=Zeroizing::new(password);lock(&app);tauri::async_runtime::spawn_blocking(move||{let Some(file)=app.dialog().file().set_title("Restore an encrypted MyTools vault").add_filter("Encrypted MyTools vault",&["mtvault","bak"]).blocking_pick_file()else{return Ok(false)};let path=file.into_path().map_err(|_|"Invalid backup file")?;let bytes=core::read(&path)?;let salt=core::header_salt(&bytes)?;let key=core::derive(&password,&salt)?;let _checked=core::open(&bytes,&key).map_err(|_|"Backup password is incorrect or the backup is damaged")?;let destination=location(&app)?;if destination.exists(){let current=core::read(&destination)?;core::commit(&destination,&bytes,&core::fingerprint(&current))?;}else{core::create(&destination,&bytes)?;}Ok(true)}).await.map_err(|_|"Backup restoration failed")?}
#[tauri::command]pub async fn vault_change_password(app:AppHandle,window:WebviewWindow,password:String,current_password:String)->Result<(),String>{authorised(&window)?;let password=Zeroizing::new(password);let current_password=Zeroizing::new(current_password);if password.chars().count()<12{return Err("Use at least 12 characters for the master password".into());}let epoch=app.state::<VaultState>().epoch.load(Ordering::SeqCst);tauri::async_runtime::spawn_blocking(move||{let previous=core::read(&location(&app)?)?;let previous_salt=core::header_salt(&previous)?;let previous_key=core::derive(&current_password,&previous_salt)?;let _checked=core::open(&previous,&previous_key).map_err(|_|"Current master password is incorrect")?;let salt=core::new_salt()?;let key=core::derive(&password,&salt)?;let state=app.state::<VaultState>();let mut g=active(&state)?;if state.epoch.load(Ordering::SeqCst)!=epoch{return Err("Vault is locked".into());}let s=g.as_mut().unwrap();let bytes=core::seal(&s.data,&key,&salt)?;core::commit(&location(&app)?,&bytes,&s.fingerprint)?;g.take();drop(g);lock(&app);Ok(())}).await.map_err(|_|"Master password change failed")?}
